/**
 * Enumeration of session revocation modes for administrator accounts.
 *
 * - All: Revoke all sessions for the authenticated admin by setting expired_at on
 *   every active session row in civic_board_admin_sessions.
 * - All_except_current: Revoke every active session except the current
 *   authenticated session (current session is inferred from JWT/session).
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IECivicBoardAdminSessionRevokeMode = "all" | "all_except_current";
